CREATE TABLE "better_supabase"."maintenance_request_checklist_items" (
  "id"                     uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"              uuid                     NOT NULL,
  "maintenance_request_id" uuid                     NOT NULL,
  "title"                  text                     NOT NULL,
  "done"                   boolean                  NOT NULL DEFAULT false,
  "done_at"                timestamp with time zone,
  "done_by"                uuid,
  "rank"                   text                     COLLATE pg_catalog."C" NOT NULL,
  "created_by"             uuid,
  "created_at"             timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "maintenance_request_checklist_items_pkey" PRIMARY KEY (id),
  CONSTRAINT "maintenance_request_checklist_items_rank_check" CHECK ((rank ~ '^[0-9A-Za-z]*[1-9A-Za-z]$'::text)),
  CONSTRAINT "maintenance_request_checklist_items_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 500)))
);

ALTER TABLE "better_supabase"."maintenance_request_checklist_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."maintenance_requests" (
  "id"               uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"        uuid                     NOT NULL,
  "number"           bigint                   NOT NULL,
  "identifier"       text                     NOT NULL,
  "title"            text                     NOT NULL,
  "body"             text,
  "parent_id"        uuid,
  "team_id"          uuid,
  "project_id"       uuid,
  "iteration_id"     uuid,
  "priority"         smallint                 NOT NULL DEFAULT 0,
  "estimate"         numeric(10,2),
  "progress"         smallint,
  "start_at"         timestamp with time zone,
  "end_at"           timestamp with time zone,
  "due_at"           timestamp with time zone,
  "pipeline_id"      uuid,
  "stage_id"         uuid,
  "stage_entered_at" timestamp with time zone,
  "state"            text                     NOT NULL DEFAULT 'backlog'::text,
  "close_reason"     text,
  "closed_at"        timestamp with time zone,
  "locked"           boolean                  NOT NULL DEFAULT false,
  "rank"             text                     COLLATE pg_catalog."C" NOT NULL DEFAULT 'V'::text,
  "archived_at"      timestamp with time zone,
  "created_by"       uuid,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "unit_id"          uuid,
  "lease_id"         uuid,
  "recurs_from"      uuid,
  CONSTRAINT "maintenance_requests_check" CHECK (((end_at IS NULL) OR (start_at IS NULL) OR (end_at >= start_at))),
  CONSTRAINT "maintenance_requests_close_reason_check" CHECK ((close_reason = ANY (ARRAY['completed'::text, 'not_planned'::text, 'duplicate'::text]))),
  CONSTRAINT "maintenance_requests_estimate_check" CHECK ((estimate >= (0)::numeric)),
  CONSTRAINT "maintenance_requests_pkey" PRIMARY KEY (id),
  CONSTRAINT "maintenance_requests_priority_check" CHECK (((priority >= 0) AND (priority <= 4))),
  CONSTRAINT "maintenance_requests_progress_check" CHECK (((progress >= 0) AND (progress <= 100))),
  CONSTRAINT "maintenance_requests_state_check"
    CHECK ((state = ANY (ARRAY['triage'::text, 'backlog'::text, 'unstarted'::text, 'started'::text, 'completed'::text, 'canceled'::text]))),
  CONSTRAINT "maintenance_requests_tenant_id_number_key" UNIQUE (tenant_id, number),
  CONSTRAINT "maintenance_requests_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 500)))
);

ALTER TABLE "better_supabase"."maintenance_requests"
  ENABLE ROW LEVEL SECURITY;

